// Pre-flight risk verification hook in PaymentForm.jsx 
const handleInitiatePayment = async (e) => { 
  e.preventDefault(); 
  setIsEvaluating(true); 
  try { 
    const riskPayload = { 
      sender_account: senderAccount, 
      receiver_account: receiverAccount, 
      amount: parseFloat(amount), 
      device_id: currentDeviceId, 
      timestamp: new Date().toISOString() 
    }; 

    // Dispatch pre-transaction risk query 
    const res = await axios.post("/api/check-risk", riskPayload); 
    const { risk_score, risk_level, required_action, grounded_evidence } = 
res.data; 

    setEvaluatedRisk({ score: risk_score, level: risk_level, evidence: 
grounded_evidence }); 

    if (required_action === "AUTO_APPROVE") { 
      executeSettlement(); 
    } else if (required_action === "OTP_STEP_UP" || required_action === 
"BIOMETRIC_FACE_MATCH") { 
      setSecurityChallengeType(required_action); 
      setIsSecurityModalOpen(true); // Open step-up challenge modal 
    } else { 
      triggerSecurityFreeze("CRITICAL_FRAUD_PREVENTED"); 
    } 
  } catch (err) { 
    console.error("Risk evaluation failure:", err); 
  } finally { 
    setIsEvaluating(false); 
  } 
}; 

