// In-memory graph centrality query in src/services/graphService.ts 
export function auditCounterpartyRisk(senderId: string, receiverId: string, 
liveLedger: Transaction[]) { 
  const tenMinutesAgo = Date.now() - 10 * 60 * 1000; 

  // 1. Calculate Receiver Fan-In Centrality (Distinct Victims transferring in 10 
mins) 
  const incomingRecent = liveLedger.filter(t =>  
    t.receiver_account === receiverId &&  
    new Date(t.timestamp).getTime() >= tenMinutesAgo 
  ); 
  const distinctSenders = new Set(incomingRecent.map(t => t.sender_account)); 
  const fanInDegree = distinctSenders.size; 

  // 2. Pair Relationship Audit 
  const priorPairTxns = liveLedger.filter(t =>  
    t.sender_account === senderId && t.receiver_account === receiverId 
  ); 

  return { 
    is_first_time_counterparty: priorPairTxns.length === 0, 
    prior_transfer_count: priorPairTxns.length, 
    receiver_fan_in_centrality: fanInDegree, 
    is_suspected_mule_hub: fanInDegree >= 5 
  }; 
}

