// Deterministic Grounded Evidence Compiler in server.ts 
function compileGroundedEvidence(senderId, requestedAmount, senderBehavior, 
pairHistory) { 
  const evidenceCards = []; 
  const historicalMean = senderBehavior.average_transaction_amount || 2500; 
  const ratio = requestedAmount / (historicalMean + 1.0); 

  // Grounded Spending Anomaly Evidence 
  if (ratio >= 2.5) { 
    evidenceCards.push({ 
      rule_id: "AMOUNT_ANOMALY", 
      title: "Unusual Spending Magnitude", 
      claim: `Transfer amount (₹${requestedAmount.toLocaleString()}) is 
${ratio.toFixed(1)}x higher than sender's historical average 
(₹${historicalMean.toLocaleString()}).`, 
      metrics: { requested: requestedAmount, average: historicalMean, multiplier: 
`${ratio.toFixed(1)}x` }, 
      supporting_ledger_ids: senderBehavior.recent_txn_sample_ids || [] 
    }); 
  } 

  // Grounded First-Time Counterparty Evidence 
  if (!pairHistory || pairHistory.total_transfers === 0) { 
    evidenceCards.push({ 
      rule_id: "FIRST_TIME_RECEIVER", 
      title: "Unestablished Beneficiary", 
      claim: "Sender has zero previous transaction history with this recipient 
account.", 
      metrics: { prior_settlements: 0, recipient_trust_index: 68.0 } 
    }); 
  } 
  return evidenceCards; 
}
